UPDATE inbox_extractions
SET status = 'completed', version = version + 1, completed_at = #{completedAt}
WHERE workspace_id = #{workspaceId} AND id = #{extractionId}
  AND status = 'awaiting_agent' AND version = #{expectedVersion}

