SELECT FROM inbox_story_candidates candidate LEFT JOIN inbox_candidate_decisions decision ON decision.candidate_id = candidate.id LEFT JOIN iterations iteration ON iteration.source_candidate_id = candidate.id WHERE candidate.workspace_id = #{workspaceId} AND candidate.extraction_id = #{extractionId}
AND (candidate.title ILIKE CONCAT('%', #{query}, '%') OR candidate.problem ILIKE CONCAT('%', #{query}, '%') OR candidate.role ILIKE CONCAT('%', #{query}, '%') OR candidate.goal ILIKE CONCAT('%', #{query}, '%') OR candidate.value ILIKE CONCAT('%', #{query}, '%'))
ORDER BY candidate.proposed_at DESC

SELECT id FROM inbox_story_candidates
WHERE workspace_id = #{workspaceId} AND id = #{candidateId}
FOR UPDATE

SELECT id, reference, workspace_id, candidate_id, candidate_sha256, action, reason,
       decided_by_user_id, decided_at, content_sha256
FROM inbox_candidate_decisions WHERE candidate_id = #{candidateId}
